/**
 * Checks of the game mode DSL that are about writing good models rather than about valid ones.
 * Validity is checked by the constraints of the metamodel (OCL and Java, see
 * {@code GamemodeValidator}), which Xtext runs as well; these checks only produce warnings and
 * information.
 */
public class RangoModeValidator extends AbstractRangoModeValidator {

	private static final String PREFIX = "no.ntnu.tdt4250.rango.gamemode.dsl.";
	public static final String UNUSED = PREFIX + "unused";
	public static final String NOT_AN_IMAGE = PREFIX + "notAnImage";
	public static final String BACKGROUND_PATH = PREFIX + "backgroundPath";
	public static final String DUPLICATE_TITLE = PREFIX + "duplicateTitle";
	public static final String USELESS_DROP_TABLE = PREFIX + "uselessDropTable";
	public static final String DIFFICULTY_ORDER = PREFIX + "difficultyOrder";

	/** Building blocks of an edition that no game mode uses only make the product harder to read. */
	@Check
	public void checkUnused(Edition edition) {
		Set<EObject> used = new HashSet<>();
		for (GameMode mode : edition.getModes()) {
			used.add(mode.getPlayer());
			used.addAll(mode.getEnemyTypes());
			for (EnemyType type : mode.getEnemyTypes()) {
				used.addAll(type.getProducedTypes());
			}
			used.addAll(mode.getPowerUps());
		}
		List<NamedElement> blocks = new ArrayList<>();
		blocks.addAll(edition.getEnemyTypes());
		blocks.addAll(edition.getPowerUps());
		blocks.addAll(edition.getPlayers());
		for (NamedElement element : blocks) {
			if (!used.contains(element)) {
				warning(kind(element) + " " + element.getName() + " is not used by any game mode", element,
						GamemodePackage.Literals.NAMED_ELEMENT__NAME, UNUSED, element.getName());
			}
		}
	}

	@Check
	public void checkSprite(EnemyType type) {
		checkImage(type, type.getSprite(), GamemodePackage.Literals.ENEMY_TYPE__SPRITE);
	}

	@Check
	public void checkSprite(PowerUp powerUp) {
		checkImage(powerUp, powerUp.getSprite(), GamemodePackage.Literals.POWER_UP__SPRITE);
	}

	private void checkImage(EObject owner, String sprite, EStructuralFeature feature) {
		if (sprite != null && !sprite.toLowerCase().endsWith(".png")) {
			warning("Sprites are PNG images in the game's assets folder, such as \"Enemy/Cactus.png\"", owner,
					feature, NOT_AN_IMAGE, sprite);
		}
	}

	/** The game looks the background up by name in its Background folder. */
	@Check
	public void checkBackground(Arena arena) {
		String background = arena.getBackground();
		if (background != null && (background.contains("/") || background.toLowerCase().endsWith(".png"))) {
			warning("The background is the name of an image in the game's Background folder, without folder"
					+ " or extension, such as \"Desert\"", arena, GamemodePackage.Literals.ARENA__BACKGROUND,
					BACKGROUND_PATH, background);
		}
	}

	/** Two modes with the same title cannot be told apart in the game's menu. */
	@Check
	public void checkTitles(Edition edition) {
		Map<String, GameMode> titles = new HashMap<>();
		for (GameMode mode : edition.getModes()) {
			if (mode.getTitle() != null && titles.putIfAbsent(mode.getTitle(), mode) != null) {
				warning("Another mode already has the title \"" + mode.getTitle() + "\"", mode,
						GamemodePackage.Literals.GAME_MODE__TITLE, DUPLICATE_TITLE);
			}
		}
	}

	/**
	 * A drop table for an enemy type that never appears where the table applies has no effect: in a mode,
	 * the enemy type is not one of the mode's; in the edition, no mode that uses the edition's tables has it.
	 */
	@Check
	public void checkUselessDropTable(DropTable table) {
		EnemyType type = table.getEnemyType();
		if (type == null || type.eIsProxy()) {
			return;
		}
		if (table.eContainer() instanceof GameMode mode) {
			if (!mode.getEnemyTypes().contains(type)) {
				warning(type.getName() + " never appears in mode " + mode.getName() + ", so this drop table has no effect",
						table, GamemodePackage.Literals.DROP_TABLE__ENEMY_TYPE, USELESS_DROP_TABLE);
			}
		} else if (table.eContainer() instanceof Edition edition) {
			boolean applies = edition.getModes().stream()
					.anyMatch(mode -> mode.getDrops().isEmpty() && mode.getEnemyTypes().contains(type));
			if (!applies) {
				warning(type.getName() + " never appears in a mode that uses the edition's drop tables, so this drop table has no effect",
						table, GamemodePackage.Literals.DROP_TABLE__ENEMY_TYPE, USELESS_DROP_TABLE);
			}
		}
	}

	/**
	 * A harder tier does not make anything easier than the tier below it, such as a hard tier with
	 * slower enemies than the medium one. A value without a modifier counts as a factor of 1. Points are
	 * a reward rather than a difficulty, so they may change either way.
	 */
	@Check
	public void checkDifficultyOrder(Edition edition) {
		List<Difficulty> tiers = new ArrayList<>(edition.getDifficulties());
		tiers.sort(Comparator.comparing(Difficulty::getTier));
		for (int i = 1; i < tiers.size(); i++) {
			Difficulty lower = tiers.get(i - 1);
			Difficulty higher = tiers.get(i);
			if (lower.getTier() == higher.getTier()) {
				continue;
			}
			for (ModifierTarget target : ModifierTarget.values()) {
				if (target == ModifierTarget.ENEMY_POINTS) {
					continue;
				}
				float below = factor(lower, target);
				float above = factor(higher, target);
				boolean easier = harderWhenLarger(target) ? above < below : above > below;
				if (easier) {
					Modifier modifier = modifier(higher, target);
					String message = "The " + higher.getTier().getLiteral() + " difficulty makes " + target.getLiteral()
							+ " easier than the " + lower.getTier().getLiteral() + " one (" + factorText(above) + " against "
							+ factorText(below) + ")";
					if (modifier != null) {
						warning(message, modifier, GamemodePackage.Literals.MODIFIER__FACTOR, DIFFICULTY_ORDER);
					} else {
						warning(message, higher, GamemodePackage.Literals.DIFFICULTY__TIER, DIFFICULTY_ORDER);
					}
				}
			}
		}
	}

	/** Faster enemies make a round harder; more health, speed, drops or time between waves make it easier. */
	private static boolean harderWhenLarger(ModifierTarget target) {
		return target == ModifierTarget.ENEMY_SPEED;
	}

	private static Modifier modifier(Difficulty difficulty, ModifierTarget target) {
		return difficulty.getModifiers().stream().filter(modifier -> modifier.getTarget() == target).findFirst().orElse(null);
	}

	private static float factor(Difficulty difficulty, ModifierTarget target) {
		Modifier modifier = modifier(difficulty, target);
		return modifier != null ? modifier.getFactor() : 1f;
	}

	private static String factorText(float factor) {
		return factor == Math.rint(factor) ? String.valueOf((int) factor) : String.valueOf(factor);
	}

	/** Tells the designer which modes are endless, which is easy to miss when reading a mode. */
	@Check
	public void checkEndless(GameMode mode) {
		if (mode.getWinConditions().isEmpty() && mode.getLevels().size() == 1
				&& mode.getLevels().get(0).getSpawning() instanceof WaveSchedule schedule && schedule.isLoop()) {
			info("Endless mode: rounds only end when they are lost", mode, GamemodePackage.Literals.NAMED_ELEMENT__NAME);
		}
	}

	private static String kind(NamedElement element) {
		if (element instanceof EnemyType) {
			return "Enemy type";
		} else if (element instanceof PowerUp) {
			return "Power-up";
		}
		return "Player profile";
	}
}
